// TestAccResourceAutoF5XCTcpLoadbalancerServicePolicyAttachments_basic verifies the
// full lifecycle of f5xc_tcp_loadbalancer_service_policy_attachments: create with two
// policies, import, then destroy.
//
// On a passing LIVE or RECORDING run, the test config is written to:
//
//	examples/resources/f5xc_tcp_loadbalancer_service_policy_attachments/resource_basic.tf
func TestAccResourceAutoF5XCTcpLoadbalancerServicePolicyAttachments_basic(t *testing.T) {
	namespace := acctest.DefaultNamespace()
	random := acctest.RandString(t, 8)
	lbName := "example-tcp-lb-att-" + random
	port := testAccTcpLoadbalancerListenPort(lbName, 0)

	cfg := testAccResourceAutoF5XCTcpLoadbalancerServicePolicyAttachmentsConfig_basic(random, lbName, namespace, port)

	acctest.VcrTestWithOptions(t, resource.TestCase{
		PreCheck:                 func() { acctest.AccTestPreCheck(t) },
		ProtoV6ProviderFactories: acctest.ProtoV6ProviderFactories(t),
		CheckDestroy:             testAccCheckTcpLoadbalancerDestroyProducer(t),
		Steps: []resource.TestStep{
			{
				Config: cfg,
				Check: resource.ComposeTestCheckFunc(
					resource.TestCheckResourceAttr("f5xc_tcp_loadbalancer_service_policy_attachments.example", "tcp_loadbalancer_name", lbName),
					resource.TestCheckResourceAttr("f5xc_tcp_loadbalancer_service_policy_attachments.example", "service_policies.#", "2"),
					resource.TestCheckResourceAttr("f5xc_tcp_loadbalancer_service_policy_attachments.example", "service_policies.0", fmt.Sprintf("tf-acc-sp-sp1-%s", random)),
					resource.TestCheckResourceAttr("f5xc_tcp_loadbalancer_service_policy_attachments.example", "service_policies.1", fmt.Sprintf("tf-acc-sp-sp2-%s", random)),
				),
			},
			{
				ResourceName:      "f5xc_tcp_loadbalancer_service_policy_attachments.example",
				ImportState:       true,
				ImportStateVerify: true,
				ImportStateIdFunc: acctest.ImportStateIDWithFields(
					"f5xc_tcp_loadbalancer_service_policy_attachments.example",
					"namespace",
					"tcp_loadbalancer_name",
				),
			},
		},
	},
		acctest.VcrTestOptions{
			DocExampleCapture: true,
			DocExampleConfig:  cfg,
		},
	)
}

